mapper.select:
SELECT NULL AS snapshot_id, COALESCE(rpt.stat_date, DATE(wo.actual_start)) AS snapshot_date, wo.resource_id, wo.resource_name, wo.work_order_id, wo.work_order_no, ROUND(wo.planned_minutes / 60.0, 2) AS planned_hours, ROUND(wo.run_minutes / 60.0, 2) AS run_hours, COALESCE(dt.dt_hours, 0) AS downtime_hours, CASE WHEN wo.planned_minutes > 0 THEN ROUND((wo.run_minutes - COALESCE(dt.dt_minutes, 0)) / wo.planned_minutes, 4) ELSE 0 END AS availability, CASE WHEN wo.plan_qty > 0 AND wo.finished_qty > 0 THEN ROUND(wo.finished_qty / wo.plan_qty, 4) ELSE 0 END AS performance, CASE WHEN wo.finished_qty > 0 THEN ROUND(wo.qualified_qty / (wo.qualified_qty + wo.defect_qty), 4) ELSE 0 END AS quality_rate, CASE WHEN wo.planned_minutes > 0 AND wo.plan_qty > 0 AND wo.finished_qty > 0 THEN ROUND( ((wo.run_minutes - COALESCE(dt.dt_minutes, 0)) / wo.planned_minutes) * (wo.finished_qty / wo.plan_qty) * (CASE WHEN (wo.qualified_qty + wo.defect_qty) > 0 THEN wo.qualified_qty / (wo.qualified_qty + wo.defect_qty) ELSE 0 END) , 4) ELSE 0 END AS oee, wo.qualified_qty AS good_qty, wo.defect_qty AS defect_qty, wo.plan_qty AS plan_qty, wo.create_time FROM ( SELECT w.work_order_id, w.work_order_no, w.resource_id, w.resource_name, w.plan_qty, w.qualified_qty, w.finished_qty, w.defect_qty, w.actual_start, w.actual_finish, w.create_time, w.del_flag, CASE WHEN w.plan_start IS NOT NULL AND w.plan_finish IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, w.plan_start, w.plan_finish) ELSE 0 END AS planned_minutes, CASE WHEN w.actual_start IS NOT NULL AND w.actual_finish IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, w.actual_start, w.actual_finish) WHEN w.actual_start IS NOT NULL THEN TIMESTAMPDIFF(MINUTE, w.actual_start, NOW()) ELSE 0 END AS run_minutes FROM mms_work_order w WHERE w.del_flag = '0' AND w.actual_start IS NOT NULL ) wo LEFT JOIN ( SELECT r.work_order_id, MAX(DATE(r.report_time)) AS stat_date FROM mms_work_report r WHERE r.del_flag = '0' GROUP BY r.work_order_id ) rpt ON rpt.work_order_id = wo.work_order_id LEFT JOIN ( SELECT d.work_order_id, SUM(d.minutes) AS dt_minutes, ROUND(SUM(d.minutes) / 60.0, 2) AS dt_hours FROM mms_downtime d WHERE d.del_flag = '0' GROUP BY d.work_order_id ) dt ON dt.work_order_id = wo.work_order_id
AND wo.resource_name LIKE CONCAT('%', #{resourceName}, '%') AND wo.work_order_no LIKE CONCAT('%', #{workOrderNo}, '%') AND COALESCE(rpt.stat_date, DATE(wo.actual_start)) >= #{params.beginTime} AND COALESCE(rpt.stat_date, DATE(wo.actual_start)) <= #{params.endTime}
ORDER BY snapshot_date DESC, wo.work_order_id DESC
